<?php

declare(strict_types=1);

namespace Y2026\Q3\SumStringsAsNumbers;

use PHPUnit\Framework\TestCase;

require_once __DIR__ . '/../../../Kata/Y2026/Q3/SumStringsAsNumbers.php';

use function Kata\Y2026\Q3\SumStringsAsNumbers\sum_strings;

class SumStringsAsNumbersTest extends TestCase
{
    public function testExamples(): void
    {
        $this->assertSame('579', sum_strings('123', '456'));
        $this->assertSame('10367', sum_strings('800', '9567'));
        $this->assertSame('8670', sum_strings('00103', '08567'));
        $this->assertSame('10', sum_strings('', '10'));
        $this->assertSame('712577413488402631964821329', sum_strings('712569312664357328695151392', '8100824045303269669937'));
        $this->assertSame('', sum_strings('', ''));
    }
}
